changeSet.sql:
UPDATE animal_colors c JOIN species s ON s.id = c.specie_id
   SET c.name = 'Café', c.version = c.version + 1
 WHERE c.name COLLATE utf8mb4_bin = 'Cafe' AND s.name = 'Canino';
UPDATE animal_colors c JOIN species s ON s.id = c.specie_id
   SET c.name = 'Hígado', c.version = c.version + 1
 WHERE c.name COLLATE utf8mb4_bin = 'Higado' AND s.name = 'Canino';
UPDATE animal_colors c JOIN species s ON s.id = c.specie_id
   SET c.name = 'Agutí', c.version = c.version + 1
 WHERE c.name COLLATE utf8mb4_bin = 'Aguti' AND s.name = 'Canino';
UPDATE animal_colors c JOIN species s ON s.id = c.specie_id
   SET c.name = 'Arlequín', c.version = c.version + 1
 WHERE c.name COLLATE utf8mb4_bin = 'Arlequin' AND s.name = 'Canino';

rollback.sql:
DELETE c FROM animal_colors c JOIN species s ON s.id = c.specie_id
 WHERE s.name = 'Canino'
   AND NOT EXISTS (SELECT 1 FROM animals a WHERE a.color_id = c.id);

